#define main g77_same_main
#include "/mnt/data/g7_7_same_side_backfire.cpp"
#undef main

template<class Pred>
vector<uint8_t> attrP(const Arena&A,Pred pred,bool filtered){vector<uint8_t>X(A.SZ,0);vector<int>rem(A.SZ,0);deque<int>q;for(int c=0;c<A.SZ;c++)if(A.valid[c]&&pred(c)){X[c]=1;q.push_back(c);}for(int c=0;c<A.SZ;c++)if(A.valid[c]&&!X[c]){int pri,wk,m,bk,t;dec4(c,pri,wk,m,bk,t);if(t==1){auto s=A.succ(c);rem[c]=s.in.size()+s.ext;}}
 while(!q.empty()){int z=q.front();q.pop_front();bool zT=pred(z);int pri,wk,m,bk,t;dec4(z,pri,wk,m,bk,t);bool zCheck=t==1&&A.incheck(pri,wk,m,bk);A.preds(z,[&](int p){if(X[p])return;int pp,pw,pm,pb,pt;dec4(p,pp,pw,pm,pb,pt);if(pt==0){if(!filtered||zT||zCheck){X[p]=1;q.push_back(p);}}else if(rem[p]>0&&--rem[p]==0){X[p]=1;q.push_back(p);}});}return X;}
int main(){initMoves();for(auto cfg:vector<tuple<string,PType,int>>{{"N-d",KNIGHT,3},{"B-d",BISHOP,3},{"B-c",BISHOP,2}}){string nm;PType typ;int ff;tie(nm,typ,ff)=cfg;Arena A(typ,{5,6,7},ff);auto TL=[&](int c){if(!A.target(c))return false;int pri,wk,m,bk,t;dec4(c,pri,wk,m,bk,t);return F(bk)<=A.file;};auto TR=[&](int c){if(!A.target(c))return false;int pri,wk,m,bk,t;dec4(c,pri,wk,m,bk,t);return F(bk)>=A.file;};auto TU=[&](int c){return A.target(c);};auto AL=attrP(A,TL,false),AR=attrP(A,TR,false),AU=attrP(A,TU,false);auto CL=attrP(A,TL,true),CR=attrP(A,TR,true),CU=attrP(A,TU,true);long long al=0,ar=0,au=0,base=0,pure=0,checkPure=0,filteredPure=0;for(int c=0;c<A.SZ;c++)if(A.valid[c]){al+=AL[c];ar+=AR[c];au+=AU[c];bool b=AL[c]||AR[c];base+=b;bool pp=AU[c]&&!b;pure+=pp;if(pp&&CU[c])checkPure++;if(CU[c]&&!CL[c]&&!CR[c])filteredPure++;}cout<<nm<<" AL="<<al<<" AR="<<ar<<" constituent_union="<<base<<" AU="<<au<<" pure="<<pure<<" CU="<<count(CU.begin(),CU.end(),1)<<" old_pure_in_CHECK="<<checkPure<<" old_pure_check_pct="<<fixed<<setprecision(6)<<(pure?100.0*checkPure/pure:0)<<" filtered_pure="<<filteredPure<<"\n";}return 0;}
